    vector<vector<char>> conflict(n, vector<char>(n, 0));
    for (int i = 0; i < m; i++) {
        conflict[pairs[i][0] - 1][pairs[i][1] - 1] = 1;
        conflict[pairs[i][1] - 1][pairs[i][0] - 1] = 1;
    }
    vector<int> group(n, 0);
    cout << countSplits(0, (int)n, 0, group, conflict) << "\n";

    return 0;
